IF DB_ID('Kaits') IS NULL BEGIN CREATE DATABASE Kaits; END GO USE Kaits; GO IF OBJECT_ID('dbo.PedidoDetalles') IS NOT NULL DROP TABLE dbo.PedidoDetalles; IF OBJECT_ID('dbo.Pedidos') IS NOT NULL DROP TABLE dbo.Pedidos; IF OBJECT_ID('dbo.Productos') IS NOT NULL DROP TABLE dbo.Productos; IF OBJECT_ID('dbo.Clientes') IS NOT NULL DROP TABLE dbo.Clientes; GO CREATE TABLE dbo.Clientes(Id INT IDENTITY(1,1) PRIMARY KEY, FullName NVARCHAR(160) NOT NULL, Dni NVARCHAR(15) NOT NULL); CREATE TABLE dbo.Productos(Id INT IDENTITY(1,1) PRIMARY KEY, Description NVARCHAR(200) NOT NULL, UnitPrice DECIMAL(18,2) NOT NULL DEFAULT(0)); CREATE TABLE dbo.Pedidos(Id INT IDENTITY(1,1) PRIMARY KEY, OrderDate DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), CustomerId INT NOT NULL, Total DECIMAL(18,2) NOT NULL DEFAULT(0), CONSTRAINT FK_Pedido_Cliente FOREIGN KEY(CustomerId) REFERENCES dbo.Clientes(Id)); CREATE TABLE dbo.PedidoDetalles(Id INT IDENTITY(1,1) PRIMARY KEY, OrderId INT NOT NULL, ProductId INT NOT NULL, ProductDescription NVARCHAR(200) NOT NULL, Quantity INT NOT NULL, UnitPrice DECIMAL(18,2) NOT NULL, Subtotal DECIMAL(18,2) NOT NULL, CONSTRAINT FK_PedidoDetalle_Pedido FOREIGN KEY(OrderId) REFERENCES dbo.Pedidos(Id), CONSTRAINT FK_PedidoDetalle_Producto FOREIGN KEY(ProductId) REFERENCES dbo.Productos(Id));